function showToast(msg){const el=document.getElementById('toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2100)}
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
function collides(x,y,r){if(x<r||y<r||x>W-r||y>H-r)return true;for(const b of buildings){const px=clamp(x,b.x,b.x+b.w),py=clamp(y,b.y,b.y+b.h);if((x-px)**2+(y-py)**2<r*r)return true}return false}
function nearestCar(){let best=null,dist=42;for(const c of cars){const d=Math.hypot(player.x-c.x,player.y-c.y);if(d<dist){best=c;dist=d}}return best}
function interaction(){if(!started||paused||dead)return;if(player.car){exitCar();return}const c=nearestCar();if(c){player.car=c;c.parked=false;c.stolen=true;c.traffic=false;c.speed=0;heat=Math.min(5,heat+1);showToast('HOTWIRE COMPLETE · KEEP MOVING');return}const m=missions[missionIndex%missions.length],pt=missionStage?m.to:m.from;if(Math.hypot(player.x-pt.x,player.y-pt.y)<55){if(missionStage===0){missionStage=1;showToast('PACKAGE SECURED · MAKE THE DROP');updateMissionUI()}else{cash+=m.reward;missionCount++;missionIndex++;missionStage=0;heat=Math.max(0,heat-1);showToast(`JOB COMPLETE · +$${m.reward}`);updateMissionUI()}return}}
function exitCar(){const c=player.car;if(!c)return;const ox=Math.cos(c.a+Math.PI/2)*28,oy=Math.sin(c.a+Math.PI/2)*28;if(!collides(c.x+ox,c.y+oy,10)){player.x=c.x+ox;player.y=c.y+oy;player.a=c.a;player.car=null;c.speed=0;showToast('BACK ON FOOT')}else showToast('NO ROOM TO GET OUT')}
function actionActive(){return keys.e||keys.E||touch.e}
function update(dt){if(!started||paused||dead)return;dt=Math.min(dt,.035);gameTime+=dt*2.7;if(gameTime>=1440)gameTime-=1440;player.invuln=Math.max(0,player.invuln-dt);
 const moveUp=keys.w||keys.ArrowUp||touch.y<-.2,moveDown=keys.s||keys.ArrowDown||touch.y>.2,moveLeft=keys.a||keys.ArrowLeft||touch.x<-.2,moveRight=keys.d||keys.ArrowRight||touch.x>.2;
 if(player.car){const c=player.car;const accelerate=moveUp||touch.boost,reverse=moveDown||touch.brake;const steer=(moveRight?1:0)-(moveLeft?1:0);c.speed+= (accelerate?195:reverse?-145:0)*dt;c.speed*=Math.pow(keys[' ']||touch.brake?.91:.985,dt*60);c.speed=clamp(c.speed,-90,250);const turn=steer*(.8+Math.min(1,Math.abs(c.speed)/120))*Math.sign(c.speed||1);c.a+=turn*dt*(keys[' ']?.65:1);const nx=c.x+Math.cos(c.a)*c.speed*dt,ny=c.y+Math.sin(c.a)*c.speed*dt;if(collides(nx,ny,13)){c.speed*=-.23;health=Math.max(0,health-(Math.abs(c.speed)>80?7:2));spawnSparks(c.x,c.y,'#f8cb72')}else{c.x=nx;c.y=ny}player.x=c.x;player.y=c.y;player.a=c.a}
 else {let vx=(moveRight?1:0)-(moveLeft?1:0),vy=(moveDown?1:0)-(moveUp?1:0);if(vx||vy){const len=Math.hypot(vx,vy);vx/=len;vy/=len;player.a=Math.atan2(vy,vx);const speed=keys.Shift?175:110,nx=player.x+vx*speed*dt,ny=player.y+vy*speed*dt;if(!collides(nx,ny,9)){player.x=nx;player.y=ny}else if(!collides(nx,player.y,9))player.x=nx;else if(!collides(player.x,ny,9))player.y=ny}}
 // Traffic cruises along the avenues and yields to buildings.
 trafficTick+=dt;for(const c of cars){if(c.traffic&&!c.parked){if(c.speed===0)c.speed=28+seeded(c.x)*22;c.x+=Math.cos(c.a)*c.speed*dt;c.y+=Math.sin(c.a)*c.speed*dt;if(c.x<20||c.x>W-20||c.y<20||c.y>H-20){c.a+=Math.PI;c.speed=35}}}
 for(const c of cars){if(c===player.car)continue;const d=Math.hypot(player.x-c.x,player.y-c.y);if(d<25&&Math.abs(player.car?.speed||0)>35){health=Math.max(0,health-10*dt);heat=Math.min(5,heat+dt*.3)}}
